Here's a robust implementation that handles debouncing, cancellation, and proper promise resolution:

```javascript
/**
 * Debounces an async function. Each call returns a promise that resolves
 * with the result of the eventual invocation, or rejects if cancelled
 * or superseded (configurable).
 *
 * @param {Function} fn - async function to debounce. Receives an AbortSignal as its last arg.
 * @param {number} wait - debounce delay in ms.
 * @param {Object} [options]
 * @param {boolean} [options.rejectOnCancel=false] - reject superseded calls instead of leaving them pending.
 * @param {boolean} [options.leading=false] - invoke on the leading edge.
 */
function debounceAsync(fn, wait, { rejectOnCancel = false, leading = false } = {}) {
  let timer = null;
  let pendingResolvers = [];      // { resolve, reject } for queued callers
  let activeController = null;    // AbortController for the in-flight call
  let lastArgs = null;

  const settlePending = (settler) => {
    const resolvers = pendingResolvers;
    pendingResolvers = [];
    resolvers.forEach(settler);
  };

  const invoke = async () => {
    const args = lastArgs;
    lastArgs = null;
    timer = null;

    // Abort any prior in-flight call before starting a new one.
    if (activeController) activeController.abort(new DOMException('Superseded', 'AbortError'));
    const controller = new AbortController();
    activeController = controller;

    const resolvers = pendingResolvers;
    pendingResolvers = [];

    try {
      const result = await fn(...args, controller.signal);
      if (!controller.signal.aborted) {
        resolvers.forEach(({ resolve }) => resolve(result));
      } else if (rejectOnCancel) {
        resolvers.forEach(({ reject }) => reject(controller.signal.reason));
      }
    } catch (err) {
      resolvers.forEach(({ reject }) => reject(err));
    } finally {
      if (activeController === controller) activeController = null;
    }
  };

  function debounced(...args) {
    lastArgs = args;

    return new Promise((resolve, reject) => {
      pendingResolvers.push({ resolve, reject });

      const callNow = leading && timer === null && !activeController;

      if (timer) clearTimeout(timer);

      if (callNow) {
        invoke();
      } else {
        timer = setTimeout(invoke, wait);
      }
    });
  }

  // Cancel any pending or in-flight invocation.
  debounced.cancel = (reason = new DOMException('Cancelled', 'AbortError')) => {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
    if (activeController) {
      activeController.abort(reason);
      activeController = null;
    }
    if (rejectOnCancel) {
      settlePending(({ reject }) => reject(reason));
    } else {
      pendingResolvers = [];
    }
    lastArgs = null;
  };

  // Force immediate invocation of the trailing call, if scheduled.
  debounced.flush = () => {
    if (timer) {
      clearTimeout(timer);
      return invoke();
    }
    return Promise.resolve();
  };

  return debounced;
}
```

### Usage

```javascript
// fn receives an AbortSignal as its final argument
const search = debounceAsync(async (query, signal) => {
  const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, { signal });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}, 300, { rejectOnCancel: true });

// Typical use in an input handler
input.addEventListener('input', async (e) => {
  try {
    const results = await search(e.target.value);
    render(results);
  } catch (err) {
    if (err.name !== 'AbortError') console.error(err);
  }
});

// Cancel everything (e.g., on component unmount)
search.cancel();

// Or run the trailing invocation immediately
await search.flush();
```

### Design notes

- **Cancellation propagates to `fetch`**: the wrapped function gets an `AbortSignal`, so in-flight network requests are actually aborted, not just ignored.
- **Stale-call protection**: if a new call lands while a previous one is still running, the previous controller is aborted so its result can't overwrite a newer one.
- **`rejectOnCancel` option**: defaults to `false` (silently drops superseded calls, similar to Lodash). Set to `true` if callers need to know their request was cancelled, paired with `try/catch` checking for `AbortError`.
- **`flush()` and `cancel()`**: standard companions to debounced functions, useful for unmount logic and "submit now" flows.
- **Leading edge**: optional, fires immediately on the first call and debounces subsequent ones.
